// Helmet smarts index — record JAH-GAIS-SMARTHELMET-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"features": 6, "battery_h": 10, "price_usd": 200};
var value = (m.features*m.battery_h/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAIS-SMARTHELMET-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAIS-SMARTHELMET-000001|' + value.toFixed(2) + ' smarts index');

